export const enum ContractType {
    Host = 0,
    Plugin = 1,
}

/**  Dispatch mechanism type — determines how function calls are routed. */
export const enum DispatchType {
    /**  Native dispatch: direct function pointer calls (zero overhead). */
    Native = 0,
    /**  VM dispatch: call through a dispatch function with loader_data. */
    VirtualMachine = 1,
}

/**  How strictly version compatibility is enforced when resolving plugins. */
export const enum Compatibility {
    /**  Exact major match and minor >= required. */
    Strict = 0,
    /**  Same major, any minor. */
    Relaxed = 1,
    /**  Any version accepted. */
    Yolo = 2,
}

/**  Type of reload phase for FFI callbacks. */
export const enum ReloadPhaseType {
    /**  Bundle is being prepared for reload. */
    Preparing = 0,
    /**  Bundle has been successfully reloaded. */
    Reloaded = 1,
    /**  Bundle reload failed. */
    Failed = 2,
    /**  Bundle is being unloaded. */
    Unloading = 3,
}

/**  How a bundle's loader-owned resources are handled when it is unloaded. */
export const enum UnloadMode {
    /**
     *  Retire-not-drop: the loader keeps the bundle's library/VM mapped for the
     *  runtime's lifetime after unload. Any raw function pointer already resolved
     *  from the bundle stays valid. This is the default, fully-safe behaviour.
     */
    Retire = 0,
    /**
     *  Reclaim: the loader frees the bundle's library/VM at unload (e.g. native
     *  `dlclose`), releasing OS resources and the on-disk file lock so a developer
     *  can rebuild and reload the bundle. Host-coordinated: the host must guarantee
     *  no thread is calling, or holds a pointer into, the bundle when it is unloaded.
     */
    Reclaim = 1,
}

/**  Runtime type identifier — identifies the language/runtime hosting plugins. */
export const enum RuntimeLanguage {
    Rust = 0,
    Cpp = 1,
    Dotnet = 2,
    Python = 3,
    Lua = 4,
    JavaScript = 5,
}

/**
 *  ABI error codes (reserved: 0-255 runtime, 256+ plugin-defined).
 * 
 *  These codes are returned by all ABI functions to indicate success or failure.
 *  The `code` field of `AbiError` uses these values.
 */
export const enum AbiErrorCode {
    /**  Success — no error. */
    Ok = 0,
    /**  Generic error — unspecified failure. */
    Generic = 1,
    /**  Buffer too small — caller must reallocate (see Buffer protocol). */
    BufferTooSmall = 2,
    /**  Panic — plugin panicked (caught by catch_unwind). */
    Panic = 3,
    /**  Not found — plugin/contract not found. */
    NotFound = 4,
    /**  Stale handle — GuestContractHandle is invalid (contract unloaded). */
    StaleHandle = 5,
    /**  Function not available — function_id >= function_count. */
    FunctionNotAvailable = 6,
    /**  Duplicate provider — same bundle already provides this contract. */
    DuplicateProvider = 7,
    /**  Invalid pointer — null or invalid pointer passed to ABI function. */
    InvalidPointer = 8,
    /**
     *  Reentrant call — a cross-call would re-enter a VM that is already
     *  executing a dispatch on the same VM. Same-VM nested calls are unsupported
     *  by the embedded interpreters (mlua, rquickjs), so the runtime rejects them
     *  rather than risk borrow/lock conflicts inside the VM.
     */
    ReentrantCall = 9,
    /**  Host contract not found — no host contract matches contract_id. */
    HostContractNotFound = 100,
    /**  Host contract version mismatch — host contract version does not match. */
    HostContractVersionMismatch = 101,
    /**  Host contract call failed — host contract function call failed. */
    HostContractCallFailed = 102,
}

/**
 *  Log severity levels for the host-supplied logger callback (`RuntimeConfig::log`).
 * 
 *  Numeric ordering is significant: lower values are more severe. A message is
 *  delivered to the callback only when `level as u32 <= RuntimeConfig::log_max_level`.
 */
export const enum LogLevel {
    /**  Unrecoverable or host-visible failures (e.g. rejected registrations). */
    Error = 1,
    /**  Recoverable anomalies the host should know about (e.g. lock poison recovery). */
    Warn = 2,
    /**  High-level lifecycle events. */
    Info = 3,
    /**  Detailed diagnostic information. */
    Debug = 4,
    /**  Very fine-grained tracing. */
    Trace = 5,
}

export const enum ParseVersionError {
    InvalidFormat = 0,
    InvalidInt = 1,
}

/**
 *  Union of dispatch mechanisms — use based on `dispatch_type`.
 * 
 *  # Safety
 *  Access the correct variant based on `GuestContractInterface::dispatch_type`:
 *  - `dispatch_type == Native` → access `.native`
 *  - `dispatch_type == VirtualMachine` → access `.vm`
 */
export type DispatchMechanisms =
    | { native: NativeDispatch }
    | { vm: VmDispatch }
;

export const POLYPLUG_ABI_VERSION: number = 1;


// ─── Helper Methods (embedded by the build script) ───

/**
 * Convert a StringView to a JavaScript string.
 * @param sv - The StringView to convert.
 * @returns The JavaScript string, or empty string if null/empty.
 */
export function stringViewToString(sv: StringView | null | undefined): string {
    if (!sv || sv.ptr === 0n || sv.len === 0) return '';
    // Note: Actual implementation requires FFI access to read memory.
    // This is a placeholder - the host/guest libraries provide actual implementation.
    return '';
}

/**
 * Strip a prefix from a string.
 * @param sv - The input StringView or string.
 * @param prefix - The prefix to strip.
 * @returns The string without prefix, or original if prefix not present.
 */
export function stripPrefix(sv: StringView | string, prefix: string): string {
    const s: string = typeof sv === 'string' ? sv : stringViewToString(sv);
    if (s.startsWith(prefix)) {
        return s.slice(prefix.length);
    }
    return s;
}

/**
 * Check if a string starts with a prefix.
 * @param sv - The input StringView or string.
 * @param prefix - The prefix to check.
 * @returns True if the string starts with the prefix.
 */
export function startsWith(sv: StringView | string, prefix: string): boolean {
    const s: string = typeof sv === 'string' ? sv : stringViewToString(sv);
    return s.startsWith(prefix);
}

/**
 * Check if a string ends with a suffix.
 * @param sv - The input StringView or string.
 * @param suffix - The suffix to check.
 * @returns True if the string ends with the suffix.
 */
export function endsWith(sv: StringView | string, suffix: string): boolean {
    const s: string = typeof sv === 'string' ? sv : stringViewToString(sv);
    return s.endsWith(suffix);
}

/**
 * Convert a StringView to a JavaScript string (shorthand alias).
 * @param sv - The StringView to convert.
 * @returns The JavaScript string, or empty string if null/empty.
 */
export function toStr(sv: StringView | null | undefined): string {
    return stringViewToString(sv);
}

/**
 * Split a string by a delimiter.
 * @param sv - The input StringView or string.
 * @param delimiter - The delimiter to split by.
 * @returns An array of strings.
 */
export function split(sv: StringView | string, delimiter: string): string[] {
    const s: string = typeof sv === 'string' ? sv : stringViewToString(sv);
    return s.split(delimiter);
}

